class Dsu {
    readonly int[] parent;
    readonly byte[] rank;                              // верхняя оценка высоты дерева
    public int Count;                                  // сколько сейчас групп
    public Dsu(int n) {
        parent = new int[n]; rank = new byte[n]; Count = n;
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    public int Find(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];
        while (parent[x] != root) {                    // сжатие: весь путь — прямо на корень
            int up = parent[x];
            parent[x] = root;
            x = up;
        }
        return root;
    }
    public bool Union(int a, int b) {
        int ra = Find(a), rb = Find(b);
        if (ra == rb) return false;                    // уже вместе: ребро лишнее
        if (rank[ra] < rank[rb]) (ra, rb) = (rb, ra);  // низкое дерево — под высокое
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) rank[ra]++;          // равные ранги: высота могла вырасти на 1
        Count--;
        return true;
    }
}

